// Verify X-Twilio-Signature.
//
// Algorithm (verified against Twilio's published test vector before this was
// written): HMAC-SHA1, base64, keyed with the account auth token, over the
// exact public webhook URL followed by every POST parameter sorted by name,
// name and value concatenated with NO delimiters.
//
// Iterates whatever parameters actually arrived. Never a fixed list: Twilio
// adds webhook parameters without notice, and validating against a hardcoded
// set silently starts rejecting valid requests.
const crypto = require('crypto');

// MUST be the exact public URL Twilio signed against. n8n sits behind Caddy and
// internally sees http://n8n:5678/..., which produces a different signature and
// a 403 on every request. Measured, not guessed. Constructed here rather than
// read from X-Forwarded-* so a forged header cannot influence what we verify.
const PUBLIC_URL = 'https://n8n.ryvodigital.com/webhook/twilio-inbound';

const item = $input.first().json;
const headers = item.headers || {};
const params = item.body || {};
const received = headers['x-twilio-signature'] || '';

const token = $env.TWILIO_AUTH_TOKEN;
const expectedSid = $env.TWILIO_ACCOUNT_SID;

function signatureBase(url, p) {
  const keys = Object.keys(p).sort();
  let s = url;
  for (const k of keys) {
    const v = p[k];
    s += k + (v === undefined || v === null ? '' : String(v));
  }
  return s;
}

let valid = false;
let reason = 'signature_mismatch';

if (!token) {
  reason = 'no_auth_token_in_env';
} else if (!received) {
  reason = 'missing_signature_header';
} else {
  const expected = crypto
    .createHmac('sha1', token)
    .update(Buffer.from(signatureBase(PUBLIC_URL, params), 'utf-8'))
    .digest('base64');
  const a = Buffer.from(expected, 'utf-8');
  const b = Buffer.from(received, 'utf-8');
  // Length check first: timingSafeEqual throws on length mismatch.
  if (a.length === b.length && crypto.timingSafeEqual(a, b)) {
    valid = true;
    reason = 'ok';
  }
}

// A valid signature proves the request came from *a* Twilio account. Confirm it
// is OURS before acting on it.
if (valid && expectedSid && params.AccountSid !== expectedSid) {
  valid = false;
  reason = 'account_sid_mismatch';
}

return [{ json: { headers, body: params, _sig: { valid, reason }, _startedAt: new Date().toISOString() } }];

// Normalise the Twilio payload into the shape the rest of the workflow uses.
// Everything downstream of here is channel-agnostic: swapping back to the Meta
// Cloud API should only require changing this node, the signature check and the
// eventual send node.
const src = $('VerifySignature').first().json;
const b = src.body || {};

// Twilio prefixes WhatsApp addresses: 'whatsapp:+351933048230'.
// leads.phone and clients.whatsapp_number store the bare E.164 number.
const strip = (v) => String(v || '').replace(/^whatsapp:/, '').trim();

const numMedia = parseInt(b.NumMedia || '0', 10) || 0;
const media = [];
for (let i = 0; i < numMedia; i++) {
  media.push({ url: b['MediaUrl' + i] || null, contentType: b['MediaContentType' + i] || null });
}

return [{
  json: {
    // Supabase REST base. Not a secret -- the project URL is public by design;
    // access is gated by the service_role key (an encrypted n8n credential) and
    // by RLS being deny-by-default. Single place to change per environment.
    supabaseUrl: 'https://txxkqskhxhwtrhbmwwig.supabase.co',

    messageSid: b.MessageSid || null,
    accountSid: b.AccountSid || null,
    from: strip(b.From),
    to: strip(b.To),
    waId: b.WaId || null,
    profileName: b.ProfileName || null,
    body: b.Body || '',
    numMedia,
    media,
    // NumMedia > 0 with an empty Body is an image/audio/location-only message.
    // Checkpoint A only has to not crash on it; Checkpoint D handles it properly.
    isNonText: numMedia > 0,
    startedAt: src._startedAt,
  }
}];

// Flatten the client lookup and decide whether we know this recipient.
const res = $input.first().json;
const n = $('Normalise').first().json;
const rows = Array.isArray(res.body) ? res.body : [];
const client = rows[0] || null;
const ca = client && Array.isArray(client.client_automations) ? client.client_automations[0] : null;

// Supabase being unreachable (free-tier auto-pause) surfaces as a non-2xx or a
// transport error, NOT as an empty result. Distinguish the two: an empty list
// means 'we do not serve this number', a bad status means 'the platform DB is
// down'. Conflating them would silently drop real leads during an outage.
const httpOk = res.statusCode >= 200 && res.statusCode < 300;

return [{
  json: {
    ...n,
    httpOk,
    statusCode: res.statusCode,
    found: httpOk && !!client && !!ca,
    errorType: !httpOk ? 'platform_db_unreachable' : (!client || !ca ? 'unknown_client' : null),
    clientId: client ? client.id : null,
    clientName: client ? client.name : null,
    clientAutomationId: ca ? ca.id : null,
    config: ca ? ca.config : null,
  }
}];

// Carry forward whether this was a first contact, plus the lead id.
const up = $input.first().json;
const c = $('FlattenClient').first().json;
const prior = $('FindExistingLead').first().json;

const priorRows = Array.isArray(prior.body) ? prior.body : [];
const isNewLead = priorRows.length === 0;
const rows = Array.isArray(up.body) ? up.body : [];
const lead = rows[0] || null;

return [{
  json: {
    ...c,
    isNewLead,
    leadId: lead ? lead.id : (priorRows[0] ? priorRows[0].id : null),
    upsertStatus: up.statusCode,
  }
}];

const SYSTEM_TEMPLATE = "You are Sofia, an assistant for Ryvo Test Client, a luxury real estate agency covering Cascais, Estoril and Lisbon.\n\nLANGUAGE - THIS OVERRIDES EVERYTHING BELOW\nDetect the language of the lead's MOST RECENT message and reply in THAT language.\nEnglish in -> English out. Portugues in -> Portugues out. Espanol in -> Espanol out.\nIf the lead switches language mid-conversation, switch with them immediately.\nSome examples in these instructions are written in Portuguese purely to illustrate a\npattern; they are NOT a signal to reply in Portuguese. Never let the language of these\ninstructions influence the language of your reply - only the lead's message decides.\n\nVoice: warm, professional, never pushy. This is luxury real estate, not a call centre.\nKeep replies WhatsApp-native: 1-3 short sentences. No email formatting, no bullet lists, no headings.\nQualify conversationally, one or two questions at a time. Never interrogate with a list.\n\nOver the conversation, gather: buyer or seller, budget range, timeline, preferred area, financing status.\n\nYOU CANNOT SEE ANY PROPERTY LISTINGS\nYou have no access to listings, prices, availability, photos or stock of any kind.\nYou therefore must NEVER state or imply that a property exists, is available, or matches\nwhat the lead asked for. This includes soft implications. All of these are FORBIDDEN\n(shown in English and Portuguese only as examples - the rule applies in every language):\n  \"we have some options in that range\"    \"temos algumas opcoes\"\n  \"yes, we have sea-view apartments\"      \"sim, temos varios imoveis assim\"\n  \"there are a few that would suit you\"   \"encontramos facilmente algo assim\"\nEven a vague \"we do have options\" is forbidden, because you cannot know it.\n\nInstead, when asked what is available or whether something exists, do BOTH of these:\n  1. Say plainly that a colleague will confirm what is currently available.\n  2. Move the conversation forward with ONE qualifying question (area, budget, timeline,\n     bedrooms, or buy-to-live vs investment).\nDescribing which AREAS the agency covers is fine - that is not a stock claim.\n\nNOT KNOWING SOMETHING IS NORMAL - IT IS NOT AN ESCALATION\nSet needs_human FALSE when you simply lack a property detail. That is your most common\nsituation and you handle it yourself.\n\nWHAT YOU MUST NOT DO\n- Never invent property details, prices, availability, or legal/tax advice.\n- Never negotiate price or terms.\n- If asked directly whether you are an AI or a bot, say honestly that you are an assistant. Never claim to be human.\n- If the lead asks to book a viewing, acknowledge warmly and say a colleague will confirm a time. Do NOT propose specific times.\n\nSET needs_human TRUE ONLY FOR THESE\n- The lead explicitly asks to speak to a person.\n- Price negotiation, offers, or contractual/legal/tax questions.\n- The lead is upset, complaining, or hostile.\n- The lead asks to book or schedule a viewing.\n- Anything you genuinely cannot handle without inventing facts BEYOND ordinary \"I don't have that detail\".\n\nIf needs_human is true, your reply must still be warm and must not promise a specific time or outcome.\n";
const REPLY_SCHEMA = {"type": "object", "properties": {"reply": {"type": "string"}, "lead_type": {"type": "string", "enum": ["buyer", "seller", "renter", "unknown"]}, "full_name": {"type": ["string", "null"]}, "budget_min": {"type": ["number", "null"]}, "budget_max": {"type": ["number", "null"]}, "timeline": {"type": ["string", "null"]}, "area": {"type": ["string", "null"]}, "qualification_notes": {"type": "object", "properties": {"financing": {"type": ["string", "null"]}, "bedrooms": {"type": ["number", "null"]}, "purpose": {"type": ["string", "null"]}}, "required": ["financing", "bedrooms", "purpose"], "additionalProperties": false}, "stage": {"type": "string", "enum": ["contacted", "qualified", "nurturing"]}, "intent": {"type": "string", "enum": ["question", "booking", "not_interested", "other"]}, "wants_booking": {"type": "boolean"}, "proposed_times": {"type": "array", "items": {"type": "string"}}, "needs_human": {"type": "boolean"}, "escalation_reason": {"type": ["string", "null"]}}, "required": ["reply", "lead_type", "full_name", "budget_min", "budget_max", "timeline", "area", "qualification_notes", "stage", "intent", "wants_booking", "proposed_times", "needs_human", "escalation_reason"], "additionalProperties": false};

// Build the Anthropic request. Everything tunable comes from
// client_automations.config so model/effort are a config change, not a node edit.
const a   = $('AfterLead').first().json;
const cfg = a.config || {};
const res = $input.first().json;

// A failed history query and a genuinely-first message are different situations.
// Only one of them is normal. Distinguish them rather than proceeding blind.
const httpOk = res.statusCode >= 200 && res.statusCode < 300;
if (!httpOk) {
  return [{ json: { ...a, fatal: true, errorType: 'history_load_failed',
                    errorMessage: 'messages query returned ' + res.statusCode } }];
}

const rows = Array.isArray(res.body) ? res.body : [];
// Query is newest-first so the LIMIT takes the LAST N. Reverse for oldest-first.
const ordered = rows.slice().reverse();

// Checkpoint A already stored this inbound message, so it IS the final user turn.
// Verify that empirically instead of reasoning about it.
const last = ordered[ordered.length - 1];
const currentTurnAlreadyPresent = !!last && last.external_id === a.messageSid;

const messages = ordered
  .filter(r => (r.body || '').trim().length > 0)
  .map(r => ({ role: r.direction === 'outbound' ? 'assistant' : 'user',
               content: r.body }));

// Anthropic requires the conversation to start with a user turn.
while (messages.length && messages[0].role !== 'user') messages.shift();

if (!currentTurnAlreadyPresent) {
  // Defensive: if A's row is somehow missing, append the live text rather than
  // calling with no current turn at all.
  messages.push({ role: 'user', content: a.body });
}
if (!messages.length) {
  return [{ json: { ...a, fatal: true, errorType: 'empty_history',
                    errorMessage: 'no usable messages to send' } }];
}

const areas = (cfg.areas || []).join(', ');
const system = SYSTEM_TEMPLATE
  .replace(/__AGENT__/g, cfg.agent_name || 'Sofia')
  .replace(/__AGENCY__/g, cfg.agency_name || a.clientName || 'the agency')
  .replace(/__AREAS__/g, areas || 'the areas we cover');

return [{ json: {
  ...a,
  fatal: false,
  currentTurnAlreadyPresent,
  historyCount: messages.length,
  claudeBody: {
    model: cfg.model || 'claude-sonnet-5',
    max_tokens: cfg.max_tokens || 1024,
    system,
    messages,
    thinking: { type: cfg.thinking || 'adaptive' },
    output_config: { effort: cfg.effort || 'low',
                     format: { type: 'json_schema', schema: REPLY_SCHEMA } },
  },
  claudeStartedAt: new Date().toISOString(),
} }];

// Defensive parse. Structured outputs (output_config.format) already constrain the
// response to the schema at the API level, so this is a BACKSTOP, not the primary
// mechanism - but it is not dead code: structured outputs do NOT hold when
// stop_reason is 'refusal' or 'max_tokens'.
const b   = $('BuildClaudeRequest').first().json;
const res = $input.first().json;
const started = b.claudeStartedAt;
const finished = new Date().toISOString();
const durationMs = Math.max(0, new Date(finished) - new Date(started));

function fail(errorType, errorMessage) {
  return [{ json: { ...b, ok: false, errorType, errorMessage, durationMs,
                    usage: null, parsed: null } }];
}

const code = res.statusCode;
if (code === 401 || code === 403) return fail('claude_auth', 'HTTP ' + code);
if (code >= 400 && code < 500)    return fail('claude_bad_request', 'HTTP ' + code);
if (!(code >= 200 && code < 300)) return fail('claude_unavailable', 'HTTP ' + code);

const body = res.body || {};
if (body.stop_reason === 'refusal')    return fail('claude_refusal', 'model declined');
if (body.stop_reason === 'max_tokens') return fail('claude_truncated', 'hit max_tokens');

let text = '';
for (const blk of (body.content || [])) if (blk.type === 'text') text += blk.text;
// Strip fences / stray prose even though structured outputs should prevent them.
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{'), e = text.lastIndexOf('}');
if (s !== -1 && e > s) text = text.slice(s, e + 1);

let p;
try { p = JSON.parse(text); } catch (err) { return fail('bad_json', String(err.message)); }

// ---------------------------------------------------------------------------
// SEMANTIC guard on the reply.
//
// Structured outputs guarantee the response matches the SCHEMA. They do not
// guarantee the reply is a sensible sentence. On 2026-09-03 a schema-valid
// response carried reply = ": corrigir - vou responder corretamente.}" and it
// was DELIVERED to a real lead. It parsed cleanly: a non-empty string in a
// string field. Only the content was broken.
//
// Not reproducible in 8 further runs, so this is rare rather than systematic --
// which is exactly why it needs a deterministic check rather than a better
// prompt. Structural markers only; nothing language-specific, since replies are
// pt-PT / en / es.
function replyLooksBroken(s) {
  const t = (s || '').trim();
  if (t.length < 15) return 'too short (' + t.length + ' chars)';
  if (':;,.})]>'.includes(t[0])) return 'starts with punctuation: ' + JSON.stringify(t[0]);
  if (t.includes('{') || t.includes('}')) return 'contains a brace - JSON leaked into the reply';
  if (t.split(/\s+/).filter(Boolean).length < 3) return 'fewer than 3 words';
  if (!/[a-zA-ZÀ-ÿ]/.test(t)) return 'contains no letters';
  return null;
}

const REQUIRED = ['reply','lead_type','stage','intent','wants_booking','needs_human'];
for (const k of REQUIRED) if (!(k in p)) return fail('bad_json', 'missing key: ' + k);
if (typeof p.reply !== 'string' || !p.reply.trim()) return fail('bad_json', 'empty reply');
if (typeof p.needs_human !== 'boolean') return fail('bad_json', 'needs_human not boolean');

const broken = replyLooksBroken(p.reply);
if (broken) return fail('bad_reply', 'reply rejected: ' + broken);

// Sanity-check extracted money before it is ever trusted downstream (spec 4.3).
// Bad structured data is worse than absent structured data.
const rejected = [];
const sane = (v) => {
  if (v === null || v === undefined) return null;
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  if (n < 1000 || n > 50000000) { rejected.push(n); return null; }
  return n;
};
p.budget_min = sane(p.budget_min);
p.budget_max = sane(p.budget_max);
if (p.budget_min !== null && p.budget_max !== null && p.budget_min > p.budget_max) {
  rejected.push(p.budget_min, p.budget_max);
  p.budget_min = null; p.budget_max = null;
}

return [{ json: { ...b, ok: true, errorType: null, errorMessage: null, durationMs,
                  usage: body.usage || null, modelUsed: body.model || null,
                  rejectedBudgets: rejected, parsed: p } }];

const p   = $('ParseClaude').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const b   = res.body || {};
return [{ json: { ...p,
  sendOk: ok,
  twilioSid: ok ? (b.sid || null) : null,
  twilioErrorCode: ok ? null : (b.code || res.statusCode),
  twilioErrorMessage: ok ? null : String(b.message || '').slice(0, 300),
} }];

// Read AfterSend explicitly. This node sits after StoreOutbound, whose output is
// an HTTP response ({statusCode, body}) - NOT the accumulated item. Using
// $input here silently produced client_automation_id: undefined, and the run
// insert failed a NOT NULL constraint invisibly because neverError swallows 4xx.
const j = $('AfterSend').first().json;
const store = $('StoreOutbound').first().json;
const lu = $('AfterLeadUpdate').first().json;
const u = j.usage || {};
return [{ json: { run: {
  client_automation_id: j.clientAutomationId,
  status: j.sendOk ? 'success' : 'error',
  started_at: j.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(j.startedAt)),
  error_type: j.sendOk ? null : 'whatsapp_send_failed',
  error_message: j.sendOk ? null : ('twilio ' + j.twilioErrorCode + ': ' + j.twilioErrorMessage),
  payload: { checkpoint: 'B1', model: j.modelUsed, claude_ms: j.durationMs,
             input_tokens: u.input_tokens ?? null, output_tokens: u.output_tokens ?? null,
             history_messages: j.historyCount, current_turn_from_history: j.currentTurnAlreadyPresent,
             needs_human: j.parsed ? j.parsed.needs_human : null,
             intent: j.parsed ? j.parsed.intent : null,
             rejected_budgets: (j.rejectedBudgets || []).length,
             twilio_sid: j.twilioSid, first_contact: j.isNewLead,
             outbound_row_status: store.statusCode,
             // B2: what the merge actually did, so an erased field would be visible
             lead_update_ok: lu.leadUpdateOk, lead_update_status: lu.leadUpdateStatus,
             stage_before: lu.stageBefore, stage_after: lu.stageAfter,
             became_qualified: lu.becameQualified,
             fields_changed: (lu.changed || []).length,
             fields_protected: (lu.kept || []).length },
} } }];

const j = $input.first().json;
return [{ json: { run: {
  client_automation_id: j.clientAutomationId,
  status: 'error',
  started_at: j.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(j.startedAt)),
  error_type: j.errorType || 'claude_failed',
  error_message: (j.errorMessage || '').slice(0, 500),
  payload: { checkpoint: 'B1', claude_ms: j.durationMs || null, sent_to_lead: false,
             history_messages: j.historyCount ?? null },
} } }];

const a = $('AfterLead').first().json;
return [{ json: { run: {
  client_automation_id: a.clientAutomationId,
  status: 'success',
  started_at: a.startedAt,
  finished_at: new Date().toISOString(),
  duration_ms: Math.max(0, new Date() - new Date(a.startedAt)),
  error_type: null, error_message: null,
  payload: { checkpoint: 'B1', duplicate_delivery: true, sent_to_lead: false },
} } }];

// ============================================================================
// The no-backwards rule is the whole of Gate B2.
//
// Claude returns null for budget when the message is about parking. Writing
// that null straight through erases what was learned three messages ago -- and
// the reply still looks perfect, so it fails INVISIBLY. Nothing downstream can
// tell an erased field from one that was never learned.
//
// So: a populated field NEVER goes back to null, and never goes back to a less
// specific value. Every field below is merged, not assigned.
// ============================================================================
const a   = $('AfterLead').first().json;
const pc  = $('ParseClaude').first().json;
const p   = pc.parsed || {};
const res = $input.first().json;

const httpOk = res.statusCode >= 200 && res.statusCode < 300;
const rows = Array.isArray(res.body) ? res.body : [];
const cur = rows[0] || null;
if (!httpOk || !cur) {
  // Do not guess at a merge against unknown current state -- that is exactly
  // how a field gets silently erased.
  return [{ json: { ...pc, leadUpdateSkipped: true,
                    leadUpdateError: 'could not read current lead (HTTP ' + res.statusCode + ')',
                    patch: null, becameQualified: false, changed: [], kept: [] } }];
}

const changed = [];   // field -> what it became
const kept    = [];   // field -> what was protected from being overwritten
const patch   = {};

// --- scalar fields: fill or improve, never blank -----------------------------
function mergeScalar(field, incoming, opts) {
  opts = opts || {};
  const before = cur[field];
  const isBlank = (v) => v === null || v === undefined ||
                         (typeof v === 'string' && v.trim() === '') ||
                         (opts.blankValues || []).includes(v);
  if (isBlank(incoming)) {
    if (!isBlank(before)) kept.push(field + '=' + before + ' (incoming was null)');
    return;
  }
  if (String(before) === String(incoming)) return;          // no change
  if (!isBlank(before) && opts.onlyIfBlank) {
    kept.push(field + '=' + before + ' (already set)');
    return;
  }
  patch[field] = incoming;
  changed.push(field + ': ' + (before === null ? 'null' : before) + ' -> ' + incoming);
}

// full_name: ProfileName seeded it at Checkpoint A. Let Claude improve on the
// seed once, then stop churning it.
const seededName = a.profileName || null;
mergeScalar('full_name', p.full_name,
            { onlyIfBlank: cur.full_name !== null && cur.full_name !== seededName });

mergeScalar('lead_type', p.lead_type, { blankValues: ['unknown'] });
mergeScalar('timeline',  p.timeline);
mergeScalar('area',      p.area);

// --- budget: sanity-checked in ParseClaude, merged here ----------------------
// ParseClaude already nulled implausible values and collected them. Widening is
// allowed (a lead who says "up to 1.5M" after "up to 800k" has genuinely moved);
// blanking is not.
mergeScalar('budget_min', p.budget_min);
mergeScalar('budget_max', p.budget_max);

// --- qualification jsonb: merge keys, never replace the object ---------------
const q = Object.assign({}, cur.qualification || {});
const notes = p.qualification_notes || {};
for (const k of ['financing', 'bedrooms', 'purpose']) {
  const v = notes[k];
  if (v === null || v === undefined || (typeof v === 'string' && !v.trim())) {
    if (q[k] !== undefined && q[k] !== null) kept.push('qualification.' + k + ' (incoming null)');
    continue;
  }
  if (String(q[k]) !== String(v)) {
    q[k] = v;
    changed.push('qualification.' + k + ': ' + (q[k] === undefined ? 'unset' : q[k]));
  }
}

// Rejected budgets go HERE, not into the numeric columns. Bad structured data is
// worse than absent structured data, because everything downstream trusts it.
const rejected = pc.rejectedBudgets || [];
if (rejected.length) {
  q.rejected_budgets = (q.rejected_budgets || []).concat(
    rejected.map(v => ({ value: v, at: new Date().toISOString(),
                         reason: 'implausible for EUR property budget' })));
  changed.push('qualification.rejected_budgets += ' + rejected.length);
}

// --- stage: monotonic along new -> contacted -> qualified --------------------
const RANK = { new: 0, nurturing: 1, contacted: 1, qualified: 2 };
const before = cur.stage || 'new';
let proposed = p.stage || null;

if (proposed === 'viewing_booked') {
  // Nothing can book until Checkpoint C. Refuse it outright rather than
  // trusting the model not to ask.
  q.stage_signals = (q.stage_signals || []).concat(
    [{ rejected: 'viewing_booked', at: new Date().toISOString() }]);
  changed.push('qualification.stage_signals += rejected viewing_booked');
  proposed = null;
}

let stage = before;
if (proposed && proposed !== before) {
  if (proposed === 'nurturing') {
    // A qualified lead is not demoted to nurturing on one quiet message; record
    // the signal instead so it is not lost.
    if (RANK[before] >= RANK.qualified) {
      q.stage_signals = (q.stage_signals || []).concat(
        [{ signal: 'nurturing', suppressed_from: before, at: new Date().toISOString() }]);
      kept.push('stage=' + before + ' (nurturing signal recorded, not applied)');
    } else {
      stage = 'nurturing';
    }
  } else if ((RANK[proposed] ?? 0) > (RANK[before] ?? 0)) {
    stage = proposed;
  } else {
    kept.push('stage=' + before + ' (model proposed ' + proposed + ', a regression)');
  }
}
if (stage !== before) { patch.stage = stage; changed.push('stage: ' + before + ' -> ' + stage); }

if (JSON.stringify(q) !== JSON.stringify(cur.qualification || {})) patch.qualification = q;

// --- always touched ---------------------------------------------------------
const now = new Date().toISOString();
patch.last_contact_at = now;
patch.updated_at = now;

// lead.qualified fires ONCE, on the transition -- not on every later message.
const becameQualified = (before !== 'qualified' && stage === 'qualified');

return [{ json: { ...pc, leadUpdateSkipped: false, leadUpdateError: null,
                  patch, becameQualified, changed, kept,
                  stageBefore: before, stageAfter: stage } }];

// Lesson 9: this node follows an HTTP call, so $input is a response envelope
// ({statusCode, headers, body}), NOT the accumulated item. Read the upstream
// node explicitly. Reading $input here is what silently produced
// client_automation_id: undefined at B1.
const m   = $('MergeLeadFields').first().json;
const res = $input.first().json;
const ok  = res.statusCode >= 200 && res.statusCode < 300;
const rows = Array.isArray(res.body) ? res.body : [];
return [{ json: { ...m,
  leadUpdateOk: ok && !m.leadUpdateSkipped,
  leadUpdateStatus: res.statusCode,
  leadAfter: rows[0] || null,
} }];
